select.where:
del_flag ='0'
and id != #{id}
and machine_code = #{machineCode}
and machine_name = #{machineName}

mapper.update:
update t_tm_machine_info
machine_name = #{machineName,jdbcType=VARCHAR}, width_min = #{widthMin,jdbcType=DECIMAL}, width_max = #{widthMax,jdbcType=DECIMAL}, thick_min = #{thickMin,jdbcType=DECIMAL}, thick_max = #{thickMax,jdbcType=DECIMAL}, quata = #{quata,jdbcType=DECIMAL}, class_shift = #{classShift,jdbcType=VARCHAR}, open_machine_class = #{openMachineClass,jdbcType=VARCHAR}, status = #{status,jdbcType=VARCHAR}, remark = #{remark,jdbcType=VARCHAR}, del_flag = #{delFlag,jdbcType=VARCHAR}, create_by = #{createBy,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=DATE}, update_by = #{updateBy,jdbcType=VARCHAR}, update_time = #{updateTime,jdbcType=DATE},
where id = #{id}

select.if:
select a.MACHINE_ID as ID,b.MACHINE_CODE,b.MACHINE_NAME from T_TM_SPECIFY_MACHINE a
inner JOIN T_TM_MACHINE_INFO b on a.MACHINE_ID=b.ID and b.STATUS = '0'
where a.DEL_FLAG='0' and a.JOB_TYPE='0' and a.TREAD_CODE=#{machineCode,jdbcType=VARCHAR}

select a.MACHINE_ID as ID,b.MACHINE_CODE,b.MACHINE_NAME from T_TM_MOUTH_PLATE a
inner JOIN T_TM_MACHINE_INFO b on a.MACHINE_ID=b.ID and b.STATUS = '0'
where a.DEL_FLAG='0' and a.STATUS='0' and a.MOUTH_PLATE_CODE=#{machineName,jdbcType=VARCHAR}
and a.MACHINE_ID not in (
select MACHINE_ID from T_TM_SPECIFY_MACHINE where DEL_FLAG='0' and JOB_TYPE='0' and
TREAD_CODE=#{machineCode,jdbcType=VARCHAR}
)

select a.ID,a.MACHINE_CODE,a.MACHINE_NAME from t_tm_machine_info a
where a.DEL_FLAG='0' and a.STATUS='0'
and a.ID not in (
select MACHINE_ID from T_TM_SPECIFY_MACHINE where DEL_FLAG='0' and JOB_TYPE='0' and
TREAD_CODE=#{machineCode,jdbcType=VARCHAR}
union
select MACHINE_ID from T_TM_MOUTH_PLATE where DEL_FLAG='0' and STATUS='0' and
MOUTH_PLATE_CODE=#{machineName,jdbcType=VARCHAR}
)

mapper.update:
merge into t_tm_machine_info a USING (
select #{MACHINE.machineCode,jdbcType=VARCHAR} machine_code, #{MACHINE.machineName,jdbcType=VARCHAR} machine_name, #{MACHINE.widthMin,jdbcType=DOUBLE} width_min, #{MACHINE.widthMax,jdbcType=DOUBLE} width_max, #{MACHINE.thickMin,jdbcType=DOUBLE} thick_min, #{MACHINE.thickMax,jdbcType=DOUBLE} thick_max, #{MACHINE.quata,jdbcType=DOUBLE} quata, #{MACHINE.classShift,jdbcType=VARCHAR} class_shift, #{MACHINE.openMachineClass,jdbcType=VARCHAR} open_machine_class, #{MACHINE.status,jdbcType=VARCHAR} status, #{MACHINE.createBy,jdbcType=VARCHAR} create_by, #{MACHINE.createTime,jdbcType=DATE} create_time, #{MACHINE.updateBy,jdbcType=VARCHAR} update_by, #{MACHINE.updateTime,jdbcType=DATE} update_time, #{MACHINE.remark,jdbcType=VARCHAR} remark from dual
) b ON (a.machine_code = b.machine_code and a.del_flag = '0') WHEN MATCHED THEN UPDATE SET a.machine_name = b.machine_name, a.width_min = b.width_min, a.width_max = b.width_max, a.thick_min = b.thick_min, a.thick_max = b.thick_max, a.quata = b.quata, a.class_shift = b.class_shift, a.open_machine_class = b.open_machine_class, a.status = b.status, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.machine_code, a.machine_name, a.width_min , a.width_max , a.thick_min , a.thick_max , a.quata , a.class_shift , a.open_machine_class , a.status , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.machine_code, b.machine_name, b.width_min, b.width_max, b.thick_min, b.thick_max, b.quata, b.class_shift, b.open_machine_class, b.status, b.create_by, sysdate, b.remark, '0' )

mapper.select:
WITH temp_table AS (
SELECT #{rowNumber}+2 row_number, #{data.machineCode} machine_code FROM dual
) select #{importLogId} importLogId, t.row_number errorRow, #{errorDetail} errorDetail, #{createBy} createBy, sysdate createTime from t_tm_machine_info m inner join temp_table t on m.machine_code = t.machine_code and m.del_flag ='0'

WITH temp_table AS (
SELECT #{rowNumber}+2 row_number, #{data.machineCode} machine_code, #{data.machineName} machine_name FROM dual
) select #{importLogId} importLogId, t.row_number errorRow, #{errorDetail} errorDetail, #{createBy} createBy, sysdate createTime from t_tm_machine_info m inner join temp_table t on m.machine_name = t.machine_name and m.del_flag ='0' and m.machine_code != t.machine_code

mapper.insert:
insert into t_tm_machine_info (ID, MACHINE_CODE, MACHINE_NAME, WIDTH_MIN, WIDTH_MAX, THICK_MIN, THICK_MAX, QUATA, CLASS_SHIFT, OPEN_MACHINE_CLASS, STATUS, REMARK, CREATE_BY) select SEQ_PUBLIC.NEXTVAL id, x.* from (
select #{MACHINE.machineCode,jdbcType=VARCHAR} machine_code, #{MACHINE.machineName,jdbcType=VARCHAR} machine_name, #{MACHINE.widthMin,jdbcType=DOUBLE} width_min, #{MACHINE.widthMax,jdbcType=DOUBLE} width_max, #{MACHINE.thickMin,jdbcType=DOUBLE} thick_min, #{MACHINE.thickMax,jdbcType=DOUBLE} thick_max, #{MACHINE.quata,jdbcType=DOUBLE} quata, #{MACHINE.classShift,jdbcType=VARCHAR} class_shift, #{MACHINE.openMachineClass,jdbcType=VARCHAR} open_machine_class, #{MACHINE.status,jdbcType=VARCHAR} status, #{MACHINE.remark,jdbcType=VARCHAR} remark, #{MACHINE.createBy,jdbcType=VARCHAR} create_by from dual
) x
